package com.waffr.app

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test

/**
 * Pbkdf2.hmacSha256 must give exactly the bytes of the app's Dart
 * implementation. pbkdf2_vectors.json is generated by Python's hashlib
 * (tool/gen_pbkdf2_vectors.py); the Dart and Swift tests check the same file.
 * On a JVM, HmacSHA256 comes from the JDK; on a phone the benchmark app
 * checks the same vectors against Android's own provider.
 */
class Pbkdf2Test {
    private data class Vector(val name: String, val password: ByteArray, val salt: ByteArray, val iterations: Int, val derived: ByteArray)

    private fun hex(text: String) = ByteArray(text.length / 2) { text.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

    private fun vectors(): List<Vector> {
        val json = javaClass.classLoader!!.getResource("pbkdf2_vectors.json")!!.readText()
        // A tiny reader for this fixed, generated file; no JSON library needed.
        val block = Regex("\\{[^{}]*\"name\": \"([^\"]+)\"[^{}]*\"password_hex\": \"([0-9a-f]*)\"[^{}]*\"salt_hex\": \"([0-9a-f]+)\"[^{}]*\"iterations\": (\\d+)[^{}]*\"derived_hex\": \"([0-9a-f]+)\"[^{}]*\\}")
        return block.findAll(json).map { m ->
            val (name, password, salt, iterations, derived) = m.destructured
            Vector(name, hex(password), hex(salt), iterations.toInt(), hex(derived))
        }.toList()
    }

    @Test
    fun everyVectorMatches() {
        val all = vectors()
        assertEquals(15, all.size)
        for (vector in all) {
            assertArrayEquals(vector.name, vector.derived, Pbkdf2.hmacSha256(vector.password, vector.salt, vector.iterations))
        }
    }

    @Test
    fun theInputArrayIsLeftAlone() {
        val password = "correct horse 1".toByteArray()
        val copy = password.copyOf()
        Pbkdf2.hmacSha256(password, ByteArray(16) { it.toByte() }, 3)
        assertArrayEquals(copy, password)
    }

    @Test
    fun outOfRangeInputIsRefused() {
        val salt = ByteArray(16)
        assertThrows(IllegalArgumentException::class.java) { Pbkdf2.hmacSha256(byteArrayOf(1), salt, 0) }
        assertThrows(IllegalArgumentException::class.java) { Pbkdf2.hmacSha256(byteArrayOf(1), salt, Pbkdf2.MAX_ITERATIONS + 1) }
        assertThrows(IllegalArgumentException::class.java) { Pbkdf2.hmacSha256(byteArrayOf(1), ByteArray(0), 1) }
        assertThrows(IllegalArgumentException::class.java) { Pbkdf2.hmacSha256(ByteArray(1025), salt, 1) }
    }

    @Test
    fun theSecretKeyFactoryAgreesOnAsciiPasswords() {
        // Benchmark-only path; checked so its timings compare like with like.
        for (vector in vectors().filter { v -> v.password.all { it in 0x21..0x7e } && v.iterations <= 4096 }) {
            assertArrayEquals(vector.name, vector.derived, Pbkdf2.secretKeyFactory(vector.password, vector.salt, vector.iterations))
        }
    }
}
